bool gc2145_detect(void)
{
    uint8_t hb_id = 0, lb_id;

    SENSOR_I2C_READ(CHIP_ID_ADDR_HB, &hb_id);
    SENSOR_I2C_READ(CHIP_ID_ADDR_LB, &lb_id);

    LOGD("%s, id: 0x%02X%02X\n", __func__, hb_id, lb_id);

    if (hb_id == CHIP_ID_VAL_HB
        && lb_id == CHIP_ID_VAL_LB)
    {
        LOGD("%s success\n", __func__);
        return true;
    }

    return false;
}

int gc2145_init(void)
{
    uint32_t size = sizeof(sensor_gc2145_init_talbe) / 2, i;

    LOGD("%s start\n", __func__);

    for (i = 0; i < size; i++)
    {
        SENSOR_I2C_WRITE(sensor_gc2145_init_talbe[i][0], sensor_gc2145_init_talbe[i][1]);
    }

    return 0;
}


int gc2145_set_ppi(media_ppi_t ppi)
{
    uint32_t size, i;
    int ret = -1;

    LOGD("%s\n", __func__);

    switch (ppi)
    {
        case PPI_480X320:
        {
            size = sizeof(sensor_gc2145_480_320_table) / 2;

            for (i = 0; i < size; i++)
