            for (i = 0; i < size; i++)
            {
                SENSOR_I2C_WRITE(sensor_gc2145_1280_720_table[i][0],
                                 sensor_gc2145_1280_720_table[i][1]);
            }
            ret = 0;
        }
        break;

        case PPI_1600X1200:
        {
            size = sizeof(sensor_gc2145_1600_1200_table) / 2;

