int gc2145_set_fps(frame_fps_t fps)
{
    int ret = 0, size = 0, i = 0;
    uint8_t width_h, width_l = 0;
    uint16_t width = 0;

    SENSOR_I2C_READ(0x97, &width_h);
    SENSOR_I2C_READ(0x98, &width_l);

    width = width_h << 8 | width_l;

    if (width == 0x0640)
    {
        size = sizeof(sensor_gc2145_1600_1200_10fps_table) / 2;

        for (i = 0; i < size; i++)
        {
            SENSOR_I2C_WRITE(sensor_gc2145_1600_1200_10fps_table[i][0],
                                sensor_gc2145_1600_1200_10fps_table[i][1]);
        }

        ret = 0;
    }
    else if (width == 0x0500) // 1280*720
    {
        switch (fps)
        {
            case FPS20:
            {
                size = sizeof(sensor_gc2145_1280_720_20fps_table) / 2;

                for (i = 0; i < size; i++)
                {
                    SENSOR_I2C_WRITE(sensor_gc2145_1280_720_20fps_table[i][0],
                                     sensor_gc2145_1280_720_20fps_table[i][1]);
