		|| (module == PM_POWER_SUB_MODULE_NAME_BAKP_SADC)
		|| (module == PM_POWER_SUB_MODULE_NAME_BAKP_PWM1)
		|| (module == PM_POWER_SUB_MODULE_NAME_BAKP_PWM0)
		|| (module == PM_POWER_SUB_MODULE_NAME_BAKP_TRNG)
