		|| (module == PM_POWER_SUB_MODULE_NAME_BAKP_SDIO)
		|| (module == PM_POWER_SUB_MODULE_NAME_BAKP_COMSEG)
		|| (module == PM_POWER_SUB_MODULE_NAME_BAKP_DMA0)
		|| (module == PM_POWER_SUB_MODULE_NAME_BAKP_DMA1)
